/**
 * AGENCIA ARLIA — MULTI-VIDEO COMMERCIAL 2D MOTION ENGINE (1080x1920)
 * 6 High-Conversion Short-Form Video Templates:
 * 1. Gastronomía & Bares (Comisiones vs Web Propia)
 * 2. Estéticas, Barberías & Spas (Turnos Online 24/7)
 * 3. Inmobiliarias & Propiedades (Basta de mandar 500 fotos)
 * 4. Sitios Web Desactualizados (Modernización en 1 Semana)
 * 5. Corralones & Ferreterías (Catálogo Digital B2B)
 * 6. Videos Virales para Negocios (Meta Ad Agencia Arlia)
 * 
 * Features:
 * - Real Pegasus Logo from IMG-20240305-WA0028.jpg
 * - Continuous kinetic spline curves with traveling glowing nodes
 * - Zero tracking lines / seconds progress lines at bottom (Clean ad style)
 * - Titanium 2D smartphone mockup with custom UI per niche
 * - CTA: "Pedinos tu presupuesto hoy mismo y en una semana tenés tu web lista, funcional y generándote clientes."
 */

const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

const W = 1080;
const H = 1920;
const CX = W / 2;
const CY = H / 2;

// Load Embedded Pegasus Logo Image
const LOGO_IMG = new Image();
LOGO_IMG.src = 'data:image/png;base64,' + '';

// Math Helpers
const clamp = (v, min = 0, max = 1) => Math.max(min, Math.min(max, v));
const lerp = (a, b, t) => a + (b - a) * t;
const easeOutQuad = (t) => t * (2 - t);
const easeOutBack = (t, s = 1.70158) => (t = t - 1) * t * ((s + 1) * t + s) + 1;
const easeOutElastic = (t) => {
  const c4 = (2 * Math.PI) / 3;
  return t === 0 ? 0 : t === 1 ? 1 : Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1;
};

function roundRect(ctx, x, y, width, height, radius) {
  if (typeof radius === 'number') {
    radius = { tl: radius, tr: radius, br: radius, bl: radius };
  } else {
    radius = Object.assign({ tl: 0, tr: 0, br: 0, bl: 0 }, radius);
  }
  ctx.beginPath();
  ctx.moveTo(x + radius.tl, y);
  ctx.lineTo(x + width - radius.tr, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius.tr);
  ctx.lineTo(x + width, y + height - radius.br);
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius.br, y + height);
  ctx.lineTo(x + radius.bl, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius.bl);
  ctx.lineTo(x, y + radius.tl);
  ctx.quadraticCurveTo(x, y, x + radius.tl, y);
  ctx.closePath();
}

// Background Splines with Traveling Glowing Nodes
const SPLINES = [
  { baseX: 160, amp: 45, freq: 0.003, speed: 1.2, width: 1.5, color: 'rgba(56, 189, 248, 0.25)', dotColor: '#38BDF8', dotSpeed: 0.08, dotOffset: 0.1 },
  { baseX: 320, amp: 60, freq: 0.0025, speed: 0.9, width: 2.0, color: 'rgba(37, 99, 235, 0.35)', dotColor: '#60A5FA', dotSpeed: 0.06, dotOffset: 0.45 },
  { baseX: 480, amp: 35, freq: 0.004, speed: 1.5, width: 1.2, color: 'rgba(56, 189, 248, 0.20)', dotColor: '#38BDF8', dotSpeed: 0.11, dotOffset: 0.75 },
  { baseX: 600, amp: 50, freq: 0.0035, speed: 1.1, width: 1.8, color: 'rgba(16, 185, 129, 0.30)', dotColor: '#34D399', dotSpeed: 0.07, dotOffset: 0.25 },
  { baseX: 760, amp: 65, freq: 0.0028, speed: 0.8, width: 2.0, color: 'rgba(37, 99, 235, 0.30)', dotColor: '#60A5FA', dotSpeed: 0.09, dotOffset: 0.60 },
  { baseX: 920, amp: 40, freq: 0.0032, speed: 1.3, width: 1.5, color: 'rgba(56, 189, 248, 0.22)', dotColor: '#38BDF8', dotSpeed: 0.08, dotOffset: 0.90 }
];

function drawPrestigeBackground(t) {
  const bgGrad = ctx.createRadialGradient(CX, CY - 200, 150, CX, CY, 1250);
  bgGrad.addColorStop(0, '#0C1630');
  bgGrad.addColorStop(0.45, '#070D1E');
  bgGrad.addColorStop(1, '#03050A');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, W, H);

  // Subtle grid
  ctx.save();
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
  ctx.lineWidth = 1;
  for (let x = 0; x <= W; x += 90) {
    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke();
  }
  for (let y = 0; y <= H; y += 90) {
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
  }
  ctx.restore();

  // Ambient floating glowing light orbs
  ctx.save();
  const orb1X = CX + Math.sin(t * 0.8) * 220;
  const orb1Y = CY - 350 + Math.cos(t * 0.6) * 160;
  const g1 = ctx.createRadialGradient(orb1X, orb1Y, 20, orb1X, orb1Y, 480);
  g1.addColorStop(0, 'rgba(37, 99, 235, 0.22)');
  g1.addColorStop(1, 'rgba(37, 99, 235, 0)');
  ctx.fillStyle = g1;
  ctx.fillRect(0, 0, W, H);

  const orb2X = CX + Math.cos(t * 0.9) * 260;
  const orb2Y = CY + 380 + Math.sin(t * 0.7) * 180;
  const g2 = ctx.createRadialGradient(orb2X, orb2Y, 20, orb2X, orb2Y, 520);
  g2.addColorStop(0, 'rgba(16, 185, 129, 0.18)');
  g2.addColorStop(1, 'rgba(16, 185, 129, 0)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();

  // Kinetic Lines & Traveling Glowing Nodes
  SPLINES.forEach((sp, idx) => {
    ctx.save();
    ctx.lineWidth = sp.width;
    ctx.strokeStyle = sp.color;

    const points = [];
    const steps = 40;
    const dy = H / steps;
    for (let i = 0; i <= steps; i++) {
      const y = i * dy;
      const x = sp.baseX + Math.sin(y * sp.freq + t * sp.speed + idx) * sp.amp + Math.cos(y * 0.0015 - t * 0.5) * (sp.amp * 0.4);
      points.push({ x, y });
    }

    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    for (let i = 1; i < points.length - 1; i++) {
      const xc = (points[i].x + points[i + 1].x) / 2;
      const yc = (points[i].y + points[i + 1].y) / 2;
      ctx.quadraticCurveTo(points[i].x, points[i].y, xc, yc);
    }
    ctx.lineTo(points[points.length - 1].x, points[points.length - 1].y);
    ctx.stroke();

    const progress = (t * sp.dotSpeed + sp.dotOffset) % 1.0;
    const pointIdx = Math.floor(progress * (points.length - 1));
    const nextIdx = Math.min(pointIdx + 1, points.length - 1);
    const subProg = (progress * (points.length - 1)) - pointIdx;
    const nodeX = lerp(points[pointIdx].x, points[nextIdx].x, subProg);
    const nodeY = lerp(points[pointIdx].y, points[nextIdx].y, subProg);

    const halo = ctx.createRadialGradient(nodeX, nodeY, 2, nodeX, nodeY, 24);
    halo.addColorStop(0, sp.dotColor);
    halo.addColorStop(0.4, sp.dotColor + '55');
    halo.addColorStop(1, sp.dotColor + '00');
    ctx.fillStyle = halo;
    ctx.beginPath(); ctx.arc(nodeX, nodeY, 24, 0, Math.PI * 2); ctx.fill();

    ctx.fillStyle = '#FFFFFF';
    ctx.shadowColor = sp.dotColor;
    ctx.shadowBlur = 12;
    ctx.beginPath(); ctx.arc(nodeX, nodeY, 4.5, 0, Math.PI * 2); ctx.fill();
    ctx.shadowBlur = 0;
    ctx.restore();
  });
}

// 2D Smartphone Vector Engine
const PHONE = { w: 780, h: 1180, r: 54, screenR: 42, bezel: 14 };

function drawSmartphone(x, y, scale = 1, tiltDeg = 0, screenRenderer) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  ctx.rotate((tiltDeg * Math.PI) / 180);

  const hw = PHONE.w / 2;
  const hh = PHONE.h / 2;

  // Deep shadow
  ctx.save();
  ctx.fillStyle = 'rgba(0, 0, 0, 0.65)';
  ctx.shadowColor = 'rgba(0, 0, 0, 0.75)';
  ctx.shadowBlur = 60;
  ctx.shadowOffsetY = 35;
  roundRect(ctx, -hw, -hh, PHONE.w, PHONE.h, PHONE.r);
  ctx.fill();
  ctx.restore();

  // Titanium Body Rim
  const titaniumGrad = ctx.createLinearGradient(-hw, -hh, hw, hh);
  titaniumGrad.addColorStop(0, '#2D3748');
  titaniumGrad.addColorStop(0.5, '#1A202C');
  titaniumGrad.addColorStop(1, '#0F172A');
  ctx.fillStyle = titaniumGrad;
  roundRect(ctx, -hw, -hh, PHONE.w, PHONE.h, PHONE.r);
  ctx.fill();

  ctx.strokeStyle = 'rgba(255, 255, 255, 0.22)';
  ctx.lineWidth = 2.5;
  roundRect(ctx, -hw, -hh, PHONE.w, PHONE.h, PHONE.r);
  ctx.stroke();

  const sw = PHONE.w - PHONE.bezel * 2;
  const sh = PHONE.h - PHONE.bezel * 2;
  const sx = -sw / 2;
  const sy = -sh / 2;

  ctx.fillStyle = '#06090F';
  roundRect(ctx, sx, sy, sw, sh, PHONE.screenR);
  ctx.fill();

  ctx.save();
  roundRect(ctx, sx, sy, sw, sh, PHONE.screenR);
  ctx.clip();

  if (typeof screenRenderer === 'function') {
    screenRenderer(ctx, sx, sy, sw, sh);
  }

  // Specular sheen
  const sheenGrad = ctx.createLinearGradient(sx, sy, sx + sw * 1.2, sy + sh);
  sheenGrad.addColorStop(0, 'rgba(255, 255, 255, 0.12)');
  sheenGrad.addColorStop(0.35, 'rgba(255, 255, 255, 0.03)');
  sheenGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0)');
  ctx.fillStyle = sheenGrad;
  ctx.fillRect(sx, sy, sw, sh);
  ctx.restore();

  // Dynamic Island
  const diW = 140, diH = 34, diX = -diW / 2, diY = sy + 16;
  ctx.fillStyle = '#000000';
  roundRect(ctx, diX, diY, diW, diH, 17);
  ctx.fill();

  ctx.fillStyle = '#0D1117';
  ctx.beginPath(); ctx.arc(diX + 32, diY + diH / 2, 6.5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#10B981';
  ctx.beginPath(); ctx.arc(diX + diW - 32, diY + diH / 2, 3, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}

// Clean Kinetic Subtitles (NO PROGRESS BARS, NO SECONDS LINE)
function drawKineticSubtitle(text, alpha = 1.0) {
  if (!text) return;
  ctx.save();
  ctx.globalAlpha = clamp(alpha, 0, 1);

  const subY = 1700;
  const pillW = 960;
  const pillH = 125;
  const pillX = (W - pillW) / 2;

  ctx.fillStyle = 'rgba(10, 15, 28, 0.94)';
  ctx.shadowColor = 'rgba(0, 0, 0, 0.8)';
  ctx.shadowBlur = 30;
  roundRect(ctx, pillX, subY, pillW, pillH, 30);
  ctx.fill();
  ctx.shadowBlur = 0;

  const borderGrad = ctx.createLinearGradient(pillX, subY, pillX + pillW, subY);
  borderGrad.addColorStop(0, 'rgba(37, 99, 235, 0.6)');
  borderGrad.addColorStop(0.5, 'rgba(56, 189, 248, 0.8)');
  borderGrad.addColorStop(1, 'rgba(16, 185, 129, 0.6)');
  ctx.strokeStyle = borderGrad;
  ctx.lineWidth = 2.5;
  roundRect(ctx, pillX, subY, pillW, pillH, 30);
  ctx.stroke();

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = '800 32px "Plus Jakarta Sans", sans-serif';

  if (text.length > 38) {
    const words = text.split(' ');
    const mid = Math.ceil(words.length / 2);
    ctx.fillStyle = '#F8FAFC';
    ctx.fillText(words.slice(0, mid).join(' '), CX, subY + 42);
    ctx.fillStyle = '#38BDF8';
    ctx.fillText(words.slice(mid).join(' '), CX, subY + 85);
  } else {
    ctx.fillStyle = '#F8FAFC';
    ctx.fillText(text, CX, subY + pillH / 2);
  }
  ctx.restore();
}

// Top Brand Badge with Pegasus Icon
function drawHeaderBadge() {
  ctx.save();
  const bw = 360, bh = 56, bx = CX - bw / 2, by = 80;
  ctx.fillStyle = 'rgba(15, 23, 42, 0.88)';
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.35)';
  ctx.lineWidth = 1.5;
  roundRect(ctx, bx, by, bw, bh, 28);
  ctx.fill(); ctx.stroke();

  // Draw small Pegasus Logo if loaded
  if (LOGO_IMG.complete && LOGO_IMG.naturalWidth > 0) {
    ctx.drawImage(LOGO_IMG, bx + 16, by + 8, 40, 40);
  } else {
    ctx.fillStyle = '#10B981';
    ctx.beginPath(); ctx.arc(bx + 32, by + bh / 2, 6, 0, Math.PI * 2); ctx.fill();
  }

  ctx.fillStyle = '#FFFFFF';
  ctx.font = '800 20px "Plus Jakarta Sans", sans-serif';
  ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
  ctx.fillText('AGENCIA ARLIA', bx + 64, by + bh / 2);

  ctx.fillStyle = '#38BDF8';
  ctx.font = '700 13px "Inter", monospace';
  ctx.fillText('• WEB & SISTEMAS', bx + 224, by + bh / 2);
  ctx.restore();
}

// Outro Scene with Pegasus Logo & New CTA
function renderOutroCommon(t, localT, customHeadline, customSub) {
  const enterProg = clamp(localT / 0.7, 0, 1);
  const logoScale = easeOutBack(enterProg);
  const logoY = 560;

  ctx.save();
  ctx.translate(CX, logoY);

  // Orbital rings
  ctx.save();
  ctx.rotate(localT * 0.25);
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.35)'; ctx.lineWidth = 3;
  ctx.setLineDash([30, 20]);
  ctx.beginPath(); ctx.arc(0, 0, 240, 0, Math.PI * 2); ctx.stroke();
  ctx.restore();

  ctx.save();
  ctx.rotate(-localT * 0.18);
  ctx.strokeStyle = 'rgba(16, 185, 129, 0.4)'; ctx.lineWidth = 2.5;
  ctx.setLineDash([50, 25]);
  ctx.beginPath(); ctx.arc(0, 0, 290, 0, Math.PI * 2); ctx.stroke();
  ctx.restore();

  // Draw Real Pegasus Logo Emblem
  ctx.scale(logoScale, logoScale);
  if (LOGO_IMG.complete && LOGO_IMG.naturalWidth > 0) {
    // Glowing circular backing
    const aura = ctx.createRadialGradient(0, 0, 50, 0, 0, 210);
    aura.addColorStop(0, 'rgba(56, 189, 248, 0.25)');
    aura.addColorStop(1, 'rgba(56, 189, 248, 0)');
    ctx.fillStyle = aura;
    ctx.beginPath(); ctx.arc(0, 0, 210, 0, Math.PI * 2); ctx.fill();

    // Draw Pegasus image centered
    const imgSize = 340;
    ctx.drawImage(LOGO_IMG, -imgSize / 2, -imgSize / 2 - 20, imgSize, imgSize);
  }
  ctx.restore();

  // Typography
  ctx.save();
  ctx.fillStyle = '#FFFFFF';
  ctx.font = '900 78px "Plus Jakarta Sans", sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('AGENCIA ARLIA', CX, 950);

  ctx.fillStyle = '#38BDF8';
  ctx.font = '700 28px "Inter", sans-serif';
  ctx.fillText(customHeadline || 'DESARROLLO WEB & AUTOMATIZACIÓN', CX, 1010);
  ctx.restore();

  // NEW MANDATORY CTA BUTTON & TEXT
  const ctaPulse = 1 + Math.sin(localT * 8) * 0.04;
  ctx.save();
  ctx.translate(CX, 1180);
  ctx.scale(ctaPulse, ctaPulse);
  const ctaGrad = ctx.createLinearGradient(-380, 0, 380, 0);
  ctaGrad.addColorStop(0, '#2563EB');
  ctaGrad.addColorStop(1, '#10B981');
  ctx.fillStyle = ctaGrad;
  ctx.shadowColor = 'rgba(37, 99, 235, 0.85)';
  ctx.shadowBlur = 40;
  roundRect(ctx, -380, -65, 760, 130, 65);
  ctx.fill();
  ctx.shadowBlur = 0;

  ctx.fillStyle = '#FFFFFF';
  ctx.font = '900 38px "Plus Jakarta Sans", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Pedinos tu presupuesto hoy 🚀', 0, 0);
  ctx.restore();

  // Value Proposition Promise (NO WEBSITE URL)
  ctx.save();
  ctx.fillStyle = '#F8FAFC';
  ctx.font = '800 32px "Plus Jakarta Sans", sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(customSub || 'En 1 semana tenés tu web lista, funcional', CX, 1340);
  ctx.fillStyle = '#10B981';
  ctx.fillText('y generándote clientes todos los días.', CX, 1390);
  ctx.restore();

  drawKineticSubtitle('Pedinos tu presupuesto hoy y en una semana tenés tu web lista.', clamp((localT) / 0.4, 0, 1));
}

