// -------------------------------------------------------------
// MASTER ROUTER
// -------------------------------------------------------------
const VIDEO_DURATIONS = {
  video_1_gastronomia: 21.0,
  video_2_estetica: 21.5,
  video_3_inmobiliaria: 22.0,
  video_4_rediseno_web: 21.0,
  video_5_corralon_ferreteria: 21.5,
  video_6_videos_virales: 21.0
};

function getVideoId() {
  if (typeof window !== 'undefined') {
    if (window.location && window.location.search) {
      const p = new URLSearchParams(window.location.search);
      const v = p.get('v');
      if (v) return v;
    }
    if (window.VIDEO_ID) return window.VIDEO_ID;
  }
  return 'video_1_gastronomia';
}

function render(t) {
  const currentVideoId = getVideoId();
  const currentDur = VIDEO_DURATIONS[currentVideoId] || 21.0;
  window.DUR = currentDur;
  t = clamp(t, 0, currentDur);
  ctx.clearRect(0, 0, W, H);
  drawPrestigeBackground(t);
  drawHeaderBadge();

  if (currentVideoId === 'video_2_estetica') {
    renderVideo2(t);
  } else if (currentVideoId === 'video_3_inmobiliaria') {
    renderVideo3(t);
  } else if (currentVideoId === 'video_4_rediseno_web') {
    renderVideo4(t);
  } else if (currentVideoId === 'video_5_corralon_ferreteria') {
    renderVideo5(t);
  } else if (currentVideoId === 'video_6_videos_virales') {
    renderVideo6(t);
  } else {
    renderVideo1(t);
  }
}

window.render = render;
render(0);
window.READY = true;
